  "armyRules": [
    {
      "name": "Forward Artillery Doctrine",
      "ref": "Armies of France (v3) page 1",
      "text": "The Artillery Forward Observer unit may call an artillery barrage twice instead of once per game. Resolve the first barrage as normal. Then, after the first barrage has been resolved, the observer may call a second (when issued a Fire order)."
    },
    {
      "name": "Highly-Motivated Reserves",
      "ref": "Armies of France (v3) page 1",
      "text": "Every Inexperienced unit that has one or more pin markers can make a test to lose one pin marker if there are any enemy units within 12\" immediately before an order is given to it. Roll a die: on a roll of 4, 5 or 6 the test is passed and the unit loses one pin marker; on a 1, 2 or 3 the test is failed and the unit retains the pin markers it has. Once this has been done, continue to test to see if the unit obeys its order in the usual way, even if they have lost their last pin marker."
    },
    {
      "name": "VB Launcher",
      "ref": "Armies of France (v3) page 1",
      "text": "The VB launcher attachment for the rifle converts the rifle into a short-range light mortar (Range 6–18\", Shots 1, PEN HE, Indirect Fire, HE 1\"). The infantryman equipped with the VB launcher can either shoot as a rifleman or as a light mortar."
    }
  ],
  "rulesCatalog": [
    {
      "name": "One-Man Turret",
      "ref": "v3 page 142",
      "text": "Combining the roles of commander, gunner, and loader into one person proved disastrous. When an order is given to a vehicle with this rule to make an Advance move, roll a D6: on a 1, 2, or 3, the vehicle moves but cannot fire its turret weapons this turn. On a 4, 5, or 6, it may move and fire normally. (Vehicles given a Run or Fire order do not need to test)."
    },
    {
      "name": "Slow… Pitifully Slow",
      "ref": "Armies of France (v3) page 4",
      "text": "The Renault FT is a Slow tank as defined by the rules and, in addition, we do not allow it to make a double-speed Run move at all. It can still be given a Run order (thereby avoiding the 'One-Man Turret' test) but moves at its basic Advance speed only."
    },
    {
      "name": "Low-velocity light anti-tank gun",
      "ref": "Armies of France (v3) page 3",
      "text": "Counts as a light anti-tank gun but with an armour penetration rating of +3 instead of the usual +4 (Range 48\", Shots 1, PEN +3)."
    },
    {
      "name": "Armoured All Round",
      "ref": "v3 page 140",
      "text": "The vehicle was designed with roughly equal thickness armor on all sides. Hits against the side or rear arcs of this vehicle do not gain the normal penetration bonuses (+1 for side, +2 for rear); all attacks are resolved against its standard Damage Value."
    },
    {
      "name": "Reinforced Front Armour",
      "ref": "v3 page 141",
      "text": "The vehicle benefits from +1 Damage Value when resolving hits scored through its front arc (for example, Damage Value 8+ becomes 9+ from the front)."
    },
    {
      "name": "Cavalry Carbines",
      "ref": "Armies of France (v3) page 3",
      "text": "These short-barreled rifles count as pistols when used on horseback and as rifles when used on foot."
    },
    {
      "name": "Motorcycles",
      "ref": "v3 page 121",
      "text": "Moves 12\" at Advance and 24\" at Run as a Wheeled vehicle, with any number of turns. Cannot enter buildings or board transports. May make an escape move when shot at as recce. Riders can dismount as part of an Advance move and fight on foot as infantry."
    },
    {
      "name": "Tough Fighters",
      "ref": "v3 page 122",
      "text": "When rolling to damage in close quarters against infantry or artillery units, it can re-roll failed rolls to damage."
    },
    {
      "name": "Tank Hunters",
      "ref": "v3 page 122",
      "text": "If a tank hunter unit wins an assault and scores damage against an armoured vehicle, damage is resolved on the full Damage Result table rather than as superficial damage. Troops do not suffer Tank Fear."
    },
    {
      "name": "Stubborn",
      "ref": "v3 page 116",
      "text": "When taking an Order test, the unit ignores pin markers for its Morale value (always tests on full base Morale)."
    },
    {
      "name": "Infiltrators",
      "ref": "v3 page 120",
      "text": "May deploy during forward deployment anywhere on the table that is more than 12\" away from enemy units (or 18\" if in enemy line of sight)."
    },
    {
      "name": "Skis",
      "ref": "Armies of France (v3) page 2",
      "text": "Ski troops ignore movement penalties for snow, ice, and other severe winter terrain conditions."
    },
    {
      "name": "Engineers",
      "ref": "v3 page 120",
      "text": "Trained in obstacle clearance and assault fortifications. Gains bonuses when attacking buildings or bunkers and clearing minefields."
    },
    {
      "name": "Command Vehicle",
      "ref": "v3 page 149",
      "text": "Adds +1 Morale bonus to itself and to friendly vehicles within 12\". Can use 'You men, snap to action!' on any one friendly vehicle within 12\"."
    },
    {
      "name": "Recce",
      "ref": "v3 page 143",
      "text": "Can react to enemy shooting or assaults by making an immediate escape move at its Advance speed in reverse or forward."
    },
    {
      "name": "Unreliable",
      "ref": "v3 page 143",
      "text": "Whenever the vehicle suffers one or more pin markers, it receives one additional pin marker due to mechanical unreliability or poor maintenance."
    },
    {
      "name": "Open-Topped",
      "ref": "v3 page 142",
      "text": "The vehicle is open-topped. Small arms fire can cause pin markers and hits from indirect fire weapons add +1 to penetration rolls. Destroyed immediately if assaulted."
    },
    {
      "name": "Flak",
      "ref": "v3 page 141",
      "text": "Can react against air attacks with defensive fire, and ignores long-range penalties against aircraft."
    }
  ],
